package com.bank.flink.window;

import java.math.BigDecimal;

// One point-of-sale transaction. eventTimeMillis is the REAL time it happened,
// not when it reached the server. This is the timestamp windows group by.
class Transaction {
    private final String accountId;
    private final BigDecimal amount;
    private final long eventTimeMillis;

    Transaction(String accountId, BigDecimal amount, long eventTimeMillis) {
        this.accountId = accountId;
        this.amount = amount;
        this.eventTimeMillis = eventTimeMillis;
    }

    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
    long getEventTimeMillis() { return eventTimeMillis; }
}
