package com.bank.flink.window;

import java.util.logging.Logger;

// Reproduces Flink's forBoundedOutOfOrderness watermark:
// watermark = maxEventTimeSeen - outOfOrdernessMillis.
// It NEVER goes backwards, exactly like a real watermark.
class WatermarkGenerator {
    private static final Logger log = Logger.getLogger(WatermarkGenerator.class.getName());

    private final long outOfOrdernessMillis;
    private long maxSeen = Long.MIN_VALUE;

    WatermarkGenerator(long outOfOrdernessMillis) {
        this.outOfOrdernessMillis = outOfOrdernessMillis;
    }

    // Called for every event; updates the max seen timestamp.
    void onEvent(long eventTimeMillis) {
        if (eventTimeMillis > maxSeen) {
            maxSeen = eventTimeMillis;
        }
    }

    // The current watermark: "event time has safely progressed to here".
    long currentWatermark() {
        if (maxSeen == Long.MIN_VALUE) {
            return Long.MIN_VALUE;
        }
        long wm = maxSeen - outOfOrdernessMillis;
        log.fine(() -> "Watermark advanced to " + wm + " (maxSeen=" + maxSeen + ")");
        return wm;
    }
}
