package com.bank.flink.window;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

// Holds the open windows as a map keyed by (accountId, windowStart).
// Each window keeps a count and a running sum of amounts.
class TumblingWindowCounter {
    private final long windowSizeMillis;
    // key = accountId + "|" + windowStart, value = accumulated state
    private final Map<String, WindowState> openWindows = new HashMap<>();

    TumblingWindowCounter(long windowSizeMillis) {
        this.windowSizeMillis = windowSizeMillis;
    }

    // Assign the event to its tumbling window start (floor to window size).
    long windowStartFor(long eventTimeMillis) {
        return eventTimeMillis - (eventTimeMillis % windowSizeMillis);
    }

    long windowEndFor(long windowStart) {
        return windowStart + windowSizeMillis;
    }

    // Add an event to its window bucket, creating the bucket if needed.
    void add(Transaction txn) {
        long start = windowStartFor(txn.getEventTimeMillis());
        String key = txn.getAccountId() + "|" + start;
        WindowState state = openWindows.computeIfAbsent(key, k -> new WindowState());
        state.count++;
        state.total = state.total.add(txn.getAmount());
    }

    Map<String, WindowState> getOpenWindows() { return openWindows; }

    // Simple mutable holder for per-window accumulation.
    static class WindowState {
        int count = 0;
        BigDecimal total = BigDecimal.ZERO;
        boolean fired = false;
    }
}
