package com.bank.flink.window;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// The EventTimeTrigger logic: a window fires exactly when the watermark
// passes its end time. Events whose window already fired go to a late side output.
class WindowTriggerEngine {
    private static final Logger log = Logger.getLogger(WindowTriggerEngine.class.getName());

    private final TumblingWindowCounter counter;
    private final WatermarkGenerator watermarks;
    private final List<Transaction> lateSideOutput = new ArrayList<>();

    WindowTriggerEngine(TumblingWindowCounter counter, WatermarkGenerator watermarks) {
        this.counter = counter;
        this.watermarks = watermarks;
    }

    // Process one event: update watermark, then either add it or route it late.
    void process(Transaction txn) {
        long windowStart = counter.windowStartFor(txn.getEventTimeMillis());
        long windowEnd = counter.windowEndFor(windowStart);
        watermarks.onEvent(txn.getEventTimeMillis());

        // If the watermark already passed this window's end, the window has fired:
        // this event is LATE. By default Flink drops it; we route it to a side output.
        if (watermarks.currentWatermark() >= windowEnd) {
            lateSideOutput.add(txn);
            log.warning(() -> "LATE event for " + txn.getAccountId()
                    + " at " + txn.getEventTimeMillis() + " -> side output");
            return;
        }
        counter.add(txn);
        log.info(() -> "Accepted " + txn.getAccountId() + " amount " + txn.getAmount()
                + " into window [" + windowStart + "," + windowEnd + ")");
    }

    // After watermark advances, fire any window whose end the watermark has crossed.
    void fireReadyWindows() {
        long wm = watermarks.currentWatermark();
        for (Map.Entry<String, TumblingWindowCounter.WindowState> e : counter.getOpenWindows().entrySet()) {
            String[] parts = e.getKey().split("\\|");
            long windowStart = Long.parseLong(parts[1]);
            long windowEnd = counter.windowEndFor(windowStart);
            TumblingWindowCounter.WindowState state = e.getValue();
            if (!state.fired && wm >= windowEnd) {
                state.fired = true;
                log.info(() -> "WINDOW FIRED account=" + parts[0]
                        + " window=[" + windowStart + "," + windowEnd + ")"
                        + " count=" + state.count + " total=" + state.total);
            }
        }
    }

    List<Transaction> getLateSideOutput() { return lateSideOutput; }
}
