package com.bank.flink.window;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: feeds an OUT-OF-ORDER stream of transactions and shows
// tumbling windows firing when the watermark passes them, plus a late event.
public class FraudWindowDemo {
    private static final Logger log = Logger.getLogger(FraudWindowDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        long windowSize = 60_000L;        // 1 minute
        long outOfOrderness = 5_000L;     // 5 seconds tolerance

        TumblingWindowCounter counter = new TumblingWindowCounter(windowSize);
        WatermarkGenerator watermarks = new WatermarkGenerator(outOfOrderness);
        WindowTriggerEngine engine = new WindowTriggerEngine(counter, watermarks);

        long base = 0L; // pretend 10:00:00 == 0ms for clarity
        // Out-of-order stream: note 59s arrives after 61s.
        Transaction[] stream = new Transaction[] {
            new Transaction("SAV2001", new BigDecimal("1200.00"), base + 5_000),   // 10:00:05
            new Transaction("SAV2001", new BigDecimal("300.00"),  base + 15_000),  // 10:00:15
            new Transaction("CUR3001", new BigDecimal("9000.00"), base + 20_000),  // 10:00:20
            new Transaction("SAV2001", new BigDecimal("450.00"),  base + 59_000),  // 10:00:59 (out of order)
            new Transaction("SAV2001", new BigDecimal("75.00"),   base + 61_000),  // 10:01:01 next window
            new Transaction("CUR3001", new BigDecimal("50.00"),   base + 90_000),  // 10:01:30 advances watermark far
            new Transaction("SAV2001", new BigDecimal("999.00"),  base + 30_000)   // 10:00:30 VERY late now
        };

        for (Transaction txn : stream) {
            engine.process(txn);
            engine.fireReadyWindows();
        }

        List<Transaction> late = engine.getLateSideOutput();
        log.info(() -> "Late side-output size = " + late.size());
    }
}

